<style>
.xd5-page .tc-contact-page{--tc-accent:#98620c;background:#f6f7f9;color:#191a1d;padding-bottom:72px;font-family:"Be Vietnam Pro",Arial,sans-serif}
.xd5-page .tc-contact-container{width:var(--wide);margin-inline:auto}
.xd5-page .tc-contact-breadcrumb{padding:26px 0;color:#626a73;font-size:12px}
.xd5-page .tc-contact-heading{max-width:800px;padding:16px 0 36px;margin-bottom:32px}
.xd5-page .tc-contact-heading>span{display:inline-block;color:#805009;font-size:12px;font-weight:700;letter-spacing:.06em}
.xd5-page .tc-contact-heading h1{font-family:inherit;font-size:clamp(32px,3.4vw,46px);line-height:1.25;margin:12px 0 18px;letter-spacing:-.025em;color:#191a1d}
.xd5-page .tc-contact-heading p{color:#626a73;font-size:16px;line-height:1.85}
.xd5-page .tc-contact-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.3fr);gap:32px;align-items:start}
.xd5-page .tc-contact-info{padding:32px;border:1px solid #191a1d;border-radius:12px;background:#191a1d;color:#fff}
.xd5-page .tc-contact-layout h2{font-size:24px;font-weight:700;line-height:1.4;margin-bottom:14px}
.xd5-page .tc-contact-info>p{color:#c4c6cc;font-size:14px;line-height:1.85}
.xd5-page .tc-contact-item{border-top-color:#ffffff26;padding:24px 0}
.xd5-page .tc-contact-item>.tc-contact-icon{background:#f0a6291f;color:#f0a629;border-radius:10px;flex-basis:44px;height:44px}
.xd5-page .tc-contact-item h3{color:#c4c6cc;font-size:12px;margin-bottom:6px}
.xd5-page .tc-contact-item p,.xd5-page .tc-contact-item a{color:#fff;font-size:14px;line-height:1.85}
.xd5-page .tc-contact-item .tc-contact-directions{color:#f0a629;font-size:12px}
.xd5-page .tc-contact-form-card{padding:36px;border:1px solid #e2e5e9;border-radius:12px;background:#fff;box-shadow:0 8px 28px #191a1d06}
.xd5-page .tc-contact-form-card>p{color:#626a73;font-size:13px}
.xd5-page .tc-contact-fields{gap:22px 20px}
.xd5-page .tc-contact-fields label{color:#30343b;font-size:13px;font-weight:600}
.xd5-page .tc-contact-fields input,.xd5-page .tc-contact-fields textarea{padding:14px 16px;border:1px solid #d8dce2;border-radius:7px;background:#fafbfc;color:#191a1d;font-size:15px;line-height:1.6}
.xd5-page .tc-contact-fields input:focus,.xd5-page .tc-contact-fields textarea:focus{border-color:#98620c;background:#fff}
.xd5-page .tc-contact-fields textarea{min-height:170px}
.xd5-page .tc-contact-fields small{color:#626a73;font-size:12px}
.xd5-page .tc-contact-fields [aria-invalid=true]{border-color:#c43939}
.xd5-page .tc-contact-form-card button{min-height:50px;margin-top:28px;padding:14px 26px;border-radius:7px;background:#98620c;color:#fff;font-family:inherit;font-weight:700}
.xd5-page .tc-contact-form-card button:hover{background:#805009}
.xd5-page .tc-contact-form-card button:disabled{opacity:.65;cursor:wait}
@media(max-width:800px){.xd5-page .tc-contact-layout{grid-template-columns:minmax(0,1fr)}.xd5-page .tc-contact-heading{padding-bottom:28px;margin-bottom:8px}}
@media(max-width:620px){.xd5-page .tc-contact-page{padding-bottom:48px}.xd5-page .tc-contact-container{width:calc(100% - 30px)}.xd5-page .tc-contact-heading h1{font-size:32px}.xd5-page .tc-contact-heading p{font-size:15px}.xd5-page .tc-contact-info,.xd5-page .tc-contact-form-card{padding:26px 20px}.xd5-page .tc-contact-layout{gap:24px}.xd5-page .tc-contact-fields{grid-template-columns:minmax(0,1fr)}.xd5-page .tc-contact-form-card button{width:100%}}
</style>
